// GENERATED by scripts/sync-shared.mjs from src/. Edit the source, then run `npm run shared:sync`.
// server-shared: the goals engine (docs/ARCHITECTURE.md "Ecosystem map" + "Habits, goals and preferences").
// Reads every tracker and produces the day's targets, a 0–100 daily score with what moved it, and the weekly
// adaptive calorie recalculation. Pure and unit-tested.

export type DailyTargets = {
  kcal: number;
  protein_g: number;
  steps: number;
  water_ml: number;
  sleep_h: number;
  workouts_per_week: number;
  smoking_limit: number | null;
};

export type GoalsRow = Partial<{
  kcal: number | null;
  protein_g: number | null;
  steps: number | null;
  water_ml: number | null;
  sleep_h: number | null;
  workouts_per_week: number | null;
  smoking_limit: number | null;
}>;

export const DEFAULT_STEPS = 8000;
export const DEFAULT_SLEEP_H = 7.5;

/** Goals row overrides; otherwise profile targets and sensible defaults (water 35 ml/kg, 8,000 steps, 7.5 h). */
export function dailyTargets(
  profile: { kcal_target: number | null; protein_target: number | null; weight_kg: number | null },
  goals: GoalsRow | null,
  trainingDays: number,
): DailyTargets {
  return {
    kcal: goals?.kcal ?? profile.kcal_target ?? 2000,
    protein_g: goals?.protein_g ?? profile.protein_target ?? 100,
    steps: goals?.steps ?? DEFAULT_STEPS,
    water_ml: goals?.water_ml ?? Math.round(((profile.weight_kg ?? 65) * 35) / 250) * 250,
    sleep_h: goals?.sleep_h ?? DEFAULT_SLEEP_H,
    workouts_per_week: goals?.workouts_per_week ?? trainingDays,
    smoking_limit: goals?.smoking_limit ?? null,
  };
}

/** Default training weekdays when the user hasn't picked them (0 = Sunday). Spread out, Monday first. */
const SPREAD: Record<number, number[]> = {
  0: [],
  1: [3],
  2: [1, 4],
  3: [1, 3, 5],
  4: [1, 2, 4, 5],
  5: [1, 2, 3, 4, 5],
  6: [1, 2, 3, 4, 5, 6],
  7: [0, 1, 2, 3, 4, 5, 6],
};

export function trainingWeekdays(prefs: { training_days: number; training_weekdays: number[] }): number[] {
  return prefs.training_weekdays.length ? prefs.training_weekdays : (SPREAD[prefs.training_days] ?? SPREAD[3]!);
}

export type ScoreInputs = {
  targets: DailyTargets;
  food: { kcal: number; protein_g: number; meals: number };
  /** Planned training day per the user's schedule. A workout on a rest day still counts as training. */
  trainingDay: boolean;
  workoutsDone: number;
  steps: number | null;
  /** One entry per active habit: adherence 0..1 for today. */
  habits: { name: string; adherence: number }[];
};

export type ScorePart = {
  key: 'food' | 'training' | 'activity' | 'habits';
  weight: number;
  earned: number;
  note: string;
};
export type DailyScore = { score: number; parts: ScorePart[]; movedBy: string[] };

const BASE = { food: 40, training: 25, activity: 15, habits: 20 } as const;

/** Calories within ±10 % of target = full credit, falling to 0 at ±50 %. */
export function kcalAdherence(kcal: number, target: number): number {
  if (target <= 0) return 0;
  const off = Math.abs(kcal - target) / target;
  if (off <= 0.1) return 1;
  return Math.max(0, 1 - (off - 0.1) / 0.4);
}

/**
 * Daily score 0–100: food 40, training 25 (training days), activity 15, habits 20. On rest days training's
 * weight is redistributed proportionally; so is the habits weight when no habits are tracked.
 */
export function dailyScore(i: ScoreInputs): DailyScore {
  const training = i.trainingDay || i.workoutsDone > 0;
  const hasHabits = i.habits.length > 0;
  const raw = {
    food: BASE.food,
    training: training ? BASE.training : 0,
    activity: BASE.activity,
    habits: hasHabits ? BASE.habits : 0,
  };
  const total = raw.food + raw.training + raw.activity + raw.habits;
  const scale = 100 / total;

  const foodShare =
    i.food.meals === 0
      ? 0
      : 0.6 * kcalAdherence(i.food.kcal, i.targets.kcal) +
        0.4 * Math.min(1, i.food.protein_g / Math.max(1, i.targets.protein_g));
  const activityShare = Math.min(1, (i.steps ?? 0) / Math.max(1, i.targets.steps));
  const habitShare = hasHabits ? i.habits.reduce((a, h) => a + h.adherence, 0) / i.habits.length : 0;

  const parts: ScorePart[] = [
    {
      key: 'food',
      weight: raw.food * scale,
      earned: raw.food * scale * foodShare,
      note:
        i.food.meals === 0
          ? 'no meals logged'
          : `${Math.round(i.food.kcal)} / ${i.targets.kcal} kcal, ${Math.round(i.food.protein_g)} g protein`,
    },
    ...(training
      ? [
          {
            key: 'training' as const,
            weight: raw.training * scale,
            earned: i.workoutsDone > 0 ? raw.training * scale : 0,
            note: i.workoutsDone > 0 ? 'workout done' : 'training day, no workout yet',
          },
        ]
      : []),
    {
      key: 'activity',
      weight: raw.activity * scale,
      earned: raw.activity * scale * activityShare,
      note:
        i.steps == null
          ? 'no steps logged'
          : `${i.steps.toLocaleString('en-IN')} / ${i.targets.steps.toLocaleString('en-IN')} steps`,
    },
    ...(hasHabits
      ? [
          {
            key: 'habits' as const,
            weight: raw.habits * scale,
            earned: raw.habits * scale * habitShare,
            note: i.habits.filter((h) => h.adherence >= 1).length + ' of ' + i.habits.length + ' habits on track',
          },
        ]
      : []),
  ];
  const score = Math.round(parts.reduce((a, p) => a + p.earned, 0));
  // "What moved it": the biggest points left on the table, in plain words.
  const movedBy = [...parts]
    .map((p) => ({ p, missing: p.weight - p.earned }))
    .filter((x) => x.missing >= 2)
    .sort((a, b) => b.missing - a.missing)
    .slice(0, 2)
    .map((x) => `${x.p.key}: ${x.p.note} (−${Math.round(x.missing)})`);
  return { score: Math.max(0, Math.min(100, score)), parts, movedBy };
}

// ─── Weekly adaptive recalculation ───────────────────────────────────────────
export type WeighIn = { date: string; weight_kg: number };
export type IntakeDay = { date: string; kcal: number };

const KCAL_PER_KG = 7700;
const WEEKLY_RATE: Record<string, number> = { fat_loss: -0.005, muscle_gain: 0.0025 }; // fraction of body weight / week

/** Least-squares slope of weight over time, in kg per day. */
export function weightSlopePerDay(weights: WeighIn[]): number | null {
  if (weights.length < 2) return null;
  const xs = weights.map((w) => Date.parse(w.date) / 86_400_000);
  const ys = weights.map((w) => w.weight_kg);
  const mx = xs.reduce((a, b) => a + b, 0) / xs.length;
  const my = ys.reduce((a, b) => a + b, 0) / ys.length;
  const den = xs.reduce((a, x) => a + (x - mx) ** 2, 0);
  if (den === 0) return null;
  return xs.reduce((a, x, k) => a + (x - mx) * (ys[k]! - my), 0) / den;
}

export type Recalc = { kcal: number; estimatedTdee: number; reason: string } | null;

/**
 * MacroFactor-style adaptation: estimated TDEE = average intake − (weight change × 7,700 kcal/kg). The new
 * target moves toward TDEE + the goal's weekly rate, by at most 10 % a week, never below the floor. Needs
 * ≥ 10 logged days and weigh-ins spanning ≥ 7 days in the window; otherwise no change.
 */
export function weeklyRecalc(o: {
  goal: string | null;
  currentKcal: number;
  floor: number;
  weights: WeighIn[];
  intake: IntakeDay[];
}): Recalc {
  const logged = o.intake.filter((d) => d.kcal > 300);
  const sorted = [...o.weights].sort((a, b) => a.date.localeCompare(b.date));
  if (logged.length < 10 || sorted.length < 2) return null;
  const span = (Date.parse(sorted.at(-1)!.date) - Date.parse(sorted[0]!.date)) / 86_400_000;
  if (span < 7) return null;
  const slope = weightSlopePerDay(sorted);
  if (slope === null) return null;
  const avgIntake = logged.reduce((a, d) => a + d.kcal, 0) / logged.length;
  const tdee = avgIntake - slope * KCAL_PER_KG;
  const bodyKg = sorted.at(-1)!.weight_kg;
  const desiredPerDay = ((WEEKLY_RATE[o.goal ?? ''] ?? 0) * bodyKg * KCAL_PER_KG) / 7;
  const ideal = tdee + desiredPerDay;
  const maxStep = o.currentKcal * 0.1;
  const next =
    Math.round(Math.max(o.floor, Math.min(o.currentKcal + maxStep, Math.max(o.currentKcal - maxStep, ideal))) / 10) *
    10;
  if (Math.abs(next - o.currentKcal) < 50) return null;
  const trend = slope * 7;
  return {
    kcal: next,
    estimatedTdee: Math.round(tdee),
    reason: `Weight trend ${trend >= 0 ? '+' : ''}${trend.toFixed(2)} kg/week on ~${Math.round(avgIntake)} kcal/day`,
  };
}
